import React, { useState, useEffect } from 'react'
import Taro from '@tarojs/taro'
import { View } from '@tarojs/components'
import { Button, ConfigProvider, TextArea, Toast } from '@nutui/nutui-react-taro'
import zhCN from '@nutui/nutui-react-taro/dist/locales/zh-CN'
import { startWorkflow } from '../../api'
import './index.scss'

function Index() {
  const [input, setInput] = useState('')
  const [loading, setLoading] = useState(false)

  useEffect(() => {
    console.log('MindFlow Client v1.1 - Using 127.0.0.1');
  }, []);

  const handleStart = async () => {
    if (!input.trim()) {
      return
    }
    setLoading(true)
    try {
      const res = await startWorkflow(input)
      console.log('Workflow Started:', res)
      Taro.navigateTo({ url: `/pages/workflow/index?id=${res.workflowId}` })
    } catch (err) {
      console.error(err)
    } finally {
      setLoading(false)
    }
  }

  return (
    <ConfigProvider locale={zhCN}>
      <View className='mindflow-home'>
        <View className='header'>
          MindFlow
        </View>
        <View className='input-area'>
          <TextArea 
            placeholder="我想写一篇关于..." 
            value={input}
            onChange={(val) => setInput(val)}
            rows={4}
          />
          <Button 
            block 
            type='primary' 
            loading={loading}
            onClick={handleStart}
            style={{ marginTop: '20px' }}
          >
            开始写作
          </Button>
        </View>
      </View>
    </ConfigProvider>
  )
}

export default Index
